import * as THREE from 'three';
// Modern right-to-left transcription using Noto Sans CJK SC, SIL OFL. Not recovered imperial calligraphy.
const maskRuns='';
export function createZhengdaGuangmingPlaqueTexture(){
  const encoded=atob(maskRuns),pixels=new Uint8Array(2048*512*4);let n=0;
  for(let i=0;i<encoded.length;i+=3){
    const count=encoded.charCodeAt(i)+(encoded.charCodeAt(i+1)<<8),a=encoded.charCodeAt(i+2)/255;
    for(let j=0;j<count;j++){
      pixels[n++]=Math.round(29+(194-29)*a);pixels[n++]=Math.round(46+(164-46)*a);
      pixels[n++]=Math.round(54+(100-54)*a);pixels[n++]=255;
    }
  }
  if(n!==pixels.length)throw new Error('ZhengdaGuangming plaque mask is incomplete');
  const texture=new THREE.DataTexture(pixels,2048,512);
  texture.name='zhengda-guangming-modern-transcription-2048';texture.colorSpace=THREE.SRGBColorSpace;
  texture.flipY=true;texture.generateMipmaps=true;texture.minFilter=THREE.LinearMipmapLinearFilter;
  texture.magFilter=THREE.LinearFilter;texture.anisotropy=8;texture.needsUpdate=true;
  texture.userData={provenance:'original-modern-transcription; Noto Sans CJK SC SIL OFL',historicalCalligraphy:false,readRightToLeft:'正大光明'};
  return texture;
}
